CREATE TABLE `cicit` (
  `id_cicit` int(11) NOT NULL AUTO_INCREMENT,
  `id_cucu` int(11) NOT NULL,
  `nama_cicit` varchar(30) NOT NULL,
  `jenis_kelamin_cicit` varchar(15) NOT NULL,
  `tgl_lahir_cicit` varchar(30) NOT NULL,
  `menantu_cicit` varchar(30) NOT NULL,
  `alamat_cicit` varchar(500) NOT NULL,
  `NoHP_cicit` varchar(15) NOT NULL,
  `foto_cicit` varchar(500) NOT NULL,
  `total_anak_cicit` int(10) NOT NULL,
  `id_provinsi` varchar(10) DEFAULT NULL,
  `id_kabupaten` varchar(10) DEFAULT NULL,
  `id_kecamatan` varchar(10) DEFAULT NULL,
  `id_desa` varchar(15) DEFAULT NULL,
  `latitude` decimal(10,8) DEFAULT NULL,
  `longitude` decimal(11,8) DEFAULT NULL,
  PRIMARY KEY (`id_cicit`),
  KEY `cicit_ibfk_1` (`id_cucu`),
  CONSTRAINT `cicit_ibfk_1` FOREIGN KEY (`id_cucu`) REFERENCES `cucu` (`id_cucu`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=142 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

