CREATE TABLE `cucu` (
  `id_cucu` int(11) NOT NULL AUTO_INCREMENT,
  `id_anak` int(10) NOT NULL,
  `nama_cucu` varchar(30) NOT NULL,
  `jenis_kelamin_cucu` varchar(15) NOT NULL,
  `tgl_lahir_cucu` varchar(30) NOT NULL,
  `menantu_cucu` varchar(30) NOT NULL,
  `alamat_cucu` varchar(500) NOT NULL,
  `NoHP_cucu` varchar(15) NOT NULL,
  `foto_cucu` varchar(500) NOT NULL,
  `total_anak_cucu` int(15) NOT NULL,
  `id_provinsi` varchar(10) DEFAULT NULL,
  `id_kabupaten` varchar(10) DEFAULT NULL,
  `id_kecamatan` varchar(10) DEFAULT NULL,
  `id_desa` varchar(15) DEFAULT NULL,
  `latitude` decimal(10,8) DEFAULT NULL,
  `longitude` decimal(11,8) DEFAULT NULL,
  PRIMARY KEY (`id_cucu`),
  KEY `madnasir` (`id_anak`),
  CONSTRAINT `madnasir` FOREIGN KEY (`id_anak`) REFERENCES `anak` (`id_anak`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=140 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
